<?php
$pageTitle=t('page_channels');$ws_id=(int)($_SESSION['workshop_id']??0);$uid=(int)($_SESSION['user_id']??0);$is_admin_channel=is_strict_admin()||is_workshop_manager();
if(!db_has_column($pdo,'chat_channels','id')){include 'includes/header.php';echo '<div class="alert alert-warning">' . t('ابتدا migrate.php را اجرا کنید.') . '</div>';include 'includes/footer.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='create_channel'&&$is_admin_channel){$name=sanitize($_POST['name']??'');if($name!==''){$st=$pdo->prepare("INSERT INTO chat_channels (workshop_id,name,description,icon,created_by) VALUES (?,?,?,?,?)");$st->execute([$ws_id,$name,sanitize($_POST['description']??''),mb_substr(trim($_POST['icon']??'💬'),0,20),$uid]);$cid=(int)$pdo->lastInsertId();$members=array_unique(array_map('intval',$_POST['members']??[]));$members[]=$uid;$ins=$pdo->prepare("INSERT IGNORE INTO chat_channel_members (channel_id,user_id,role) VALUES (?,?,'member')");foreach($members as $member)if($member)$ins->execute([$cid,$member]);operations_system_chat_message($pdo,$ws_id,$uid,strtr(t('📢 کانال جدید «{name}» ساخته شد.'), ['{name}' => $name]),$cid);showToast(t('کانال ساخته شد.'));}redirect('index.php?page=chat&view=channels');}
 if($action==='send_channel'){$cid=(int)$_POST['channel_id'];$message=sanitize($_POST['message']??'');$check=$pdo->prepare("SELECT c.id FROM chat_channels c LEFT JOIN chat_channel_members m ON m.channel_id=c.id AND m.user_id=? WHERE c.id=? AND c.workshop_id=? AND c.status='active' AND (?=1 OR m.user_id IS NOT NULL)");$check->execute([$uid,$cid,$ws_id,$is_admin_channel?1:0]);if(!$check->fetchColumn()){showToast(t('عضو این کانال نیستید.'),'error');}elseif($message!==''){$st=$pdo->prepare("INSERT INTO chat_messages (sender_id,receiver_id,message,attachment_type,is_read,workshop_id,channel_id,is_system) VALUES (?,0,?,'emoji',0,?,?,0)");$st->execute([$uid,$message,$ws_id,$cid]);showToast(t('پیام ارسال شد.'));}redirect('index.php?page=chat&view=channels&channel_id='.$cid);}
 if($action==='toggle_channel'&&$is_admin_channel){$pdo->prepare("UPDATE chat_channels SET status=IF(status='active','inactive','active') WHERE id=? AND workshop_id=?")->execute([(int)$_POST['channel_id'],$ws_id]);redirect('index.php?page=chat&view=channels');}
}
$channels=[];$people=[];$selected=(int)($_GET['channel_id']??0);$messages=[];
try{$sql="SELECT c.*,COUNT(m.user_id) member_count FROM chat_channels c LEFT JOIN chat_channel_members m ON m.channel_id=c.id WHERE c.workshop_id=? AND (c.status='active' OR ?=1) AND (?=1 OR EXISTS(SELECT 1 FROM chat_channel_members mm WHERE mm.channel_id=c.id AND mm.user_id=?)) GROUP BY c.id ORDER BY c.created_at DESC";$st=$pdo->prepare($sql);$st->execute([$ws_id,$is_admin_channel?1:0,$is_admin_channel?1:0,$uid]);$channels=$st->fetchAll();$st=$pdo->prepare("SELECT u.id,u.full_name FROM users u JOIN workshop_personnel wp ON wp.user_id=u.id WHERE wp.workshop_id=? AND wp.status='active' ORDER BY u.full_name");$st->execute([$ws_id]);$people=$st->fetchAll();if(!$selected&&!empty($channels))$selected=(int)$channels[0]['id'];if($selected){$st=$pdo->prepare("SELECT cm.*,u.full_name,u.avatar FROM chat_messages cm JOIN users u ON u.id=cm.sender_id WHERE cm.workshop_id=? AND cm.channel_id=? ORDER BY cm.created_at ASC");$st->execute([$ws_id,$selected]);$messages=$st->fetchAll();}}catch(Throwable $e){}
include 'includes/header.php';
?>
<div class="d-flex justify-between align-center mb-4 animate-in"><h2>📣 <?= t('page_channels') ?></h2><?php if($is_admin_channel):?><button class="btn btn-primary" onclick="openModal('newChannelModal')">＋ <?= t('کانال جدید') ?></button><?php endif;?></div>
<div class="tabs mb-4 animate-in chat-mode-tabs"><a href="index.php?page=chat" class="tab"><?= t('💬 گفت‌وگو') ?></a><a href="index.php?page=chat&view=channels" class="tab active">📣 <?= t('کانال‌ها') ?></a></div>
<div style="display:grid;grid-template-columns:260px minmax(0,1fr);gap:16px" class="channel-layout"><aside class="card"><div class="card-header"><h3 class="card-title"><?= t('کانال‌ها') ?></h3></div><?php foreach($channels as $c):?><a href="index.php?page=chat&view=channels&channel_id=<?=$c['id']?>" style="display:flex;gap:9px;align-items:center;padding:10px;border-bottom:1px solid var(--border);text-decoration:none;color:inherit;background:<?=$selected===$c['id']?'rgba(99,102,241,.09)':'transparent'?>"><span style="font-size:22px"><?=htmlspecialchars($c['icon'])?></span><span style="flex:1"><strong style="font-size:13px"><?=htmlspecialchars($c['name'])?></strong><small class="text-muted" style="display:block"><?=$c['member_count']?> <?= t('عضو') ?></small></span><?php if($is_admin_channel):?><form method="post" onclick="event.stopPropagation()"><?= get_csrf_field() ?><input type="hidden" name="action" value="toggle_channel"><input type="hidden" name="channel_id" value="<?=$c['id']?>"><button class="btn btn-ghost btn-sm"><?=$c['status']==='active'?'🔕':'🔔'?></button></form><?php endif;?></a><?php endforeach;?><?php if(empty($channels)):?><p class="text-muted text-center" style="padding:25px"><?= t('کانالی ندارید.') ?></p><?php endif;?></aside><main class="card" style="min-height:500px;display:flex;flex-direction:column"><div class="card-header"><h3 class="card-title"><?php $cur=array_values(array_filter($channels,fn($c)=>(int)$c['id']===$selected));echo $cur?htmlspecialchars($cur[0]['icon'].' '.$cur[0]['name']):t('کانال را انتخاب کنید');?></h3></div><div style="flex:1;overflow:auto;max-height:460px" id="channelMessages"><?php foreach($messages as $m):$mine=(int)$m['sender_id']===$uid;?><div style="display:flex;justify-content:<?=$mine?'flex-start':'flex-end'?>;margin:9px 0"><div style="max-width:75%;padding:9px 12px;border-radius:12px;background:<?=$mine?'var(--primary)':'var(--bg)'?>;color:<?=$mine?'#fff':'var(--text)'?>"><strong style="font-size:10px"><?= $m['is_system'] ? t('سیستم') : htmlspecialchars($m['full_name'])?></strong><div style="font-size:13px;margin-top:3px"><?=nl2br(htmlspecialchars($m['message']))?></div><small style="opacity:.65"><?=substr($m['created_at'],11,5)?></small></div></div><?php endforeach;?><?php if(empty($messages)&&$selected):?><p class="text-muted text-center" style="padding:40px"><?= t('هنوز پیامی ثبت نشده است.') ?></p><?php endif;?></div><?php if($selected):?><form method="post" class="d-flex gap-2" style="border-top:1px solid var(--border);padding-top:12px"><?= get_csrf_field() ?><input type="hidden" name="action" value="send_channel"><input type="hidden" name="channel_id" value="<?=$selected?>"><input name="message" class="form-control" required placeholder="<?= t('پیام در کانال...') ?>"><button class="btn btn-primary"><?= t('btn_submit') ?></button></form><?php endif;?></main></div>
<?php if($is_admin_channel):?><div id="newChannelModal" class="modal-overlay hidden"><div class="modal glass-modal"><div class="modal-header"><h3 class="modal-title"><?= t('کانال جدید') ?></h3><button class="modal-close" onclick="closeModal('newChannelModal')">✕</button></div><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="create_channel"><div class="modal-body"><div class="form-row"><div class="form-group"><label class="form-label"><?= t('wh_name') ?> *</label><input name="name" class="form-control" required></div><div class="form-group"><label class="form-label"><?= t('آیکون') ?></label><input name="icon" class="form-control" value="💬"></div></div><div class="form-group"><label class="form-label"><?= t('توضیح') ?></label><input name="description" class="form-control"></div><div class="form-group"><label class="form-label"><?= t('اعضا') ?></label><div style="max-height:180px;overflow:auto;border:1px solid var(--border);padding:8px"><?php foreach($people as $p):?><label class="form-check"><input type="checkbox" name="members[]" value="<?=$p['id']?>"><span><?=htmlspecialchars($p['full_name'])?></span></label><?php endforeach;?></div></div></div><div class="modal-footer"><button class="btn btn-primary"><?= t('ساخت کانال') ?></button></div></form></div></div><?php endif;?><style>@media(max-width:768px){.channel-layout{grid-template-columns:1fr!important}}</style><?php include 'includes/footer.php'; ?>
